package Redirects;
# Where to send a user after sign-in.
use strict;
use warnings;

sub after_login {
    my ($target) = @_;
    return '/' unless defined $target && length $target;
    return $target;
}

1;

use strict;
use warnings;
use Test::More;
use Redirects;

is(Redirects::after_login(undef), '/', 'defaults to home');

done_testing();
